sys_script.script:
(function executeRule(current, previous) {

    var NOTIFICATION_TABLE =
        'x_snc_visaguardi_0_student_notification';


    /* =====================================================
       HELPER
    ===================================================== */

    function createNotification(
        userID,
        title,
        message,
        type
    ) {

        if (!userID) {

            return;

        }


        var notification =
            new GlideRecord(
                NOTIFICATION_TABLE
            );

        notification.initialize();


        notification.setValue(
            'user',
            userID
        );


        notification.setValue(
            'title',
            title
        );


        notification.setValue(
            'message',
            message
        );


        notification.setValue(
            'notification_type',
            type
        );


        notification.setValue(
            'case',
            current.getUniqueValue()
        );


        notification.setValue(
            'is_read',
            false
        );


        notification.setValue(
            'created',
            gs.nowDateTime()
        );


        notification.insert();

    }


    /* =====================================================
       STUDENT
    ===================================================== */

    var studentID = '';


    /*
     * Change this field if your Visa Cases table
     * uses another student field.
     */

    if (
        current.student &&
        !current.student.nil()
    ) {

        studentID =
            current.student.toString();

    }

    else if (
        current.applicant &&
        !current.applicant.nil()
    ) {

        studentID =
            current.applicant.toString();

    }


    /* =====================================================
       1. ADDITIONAL DOCUMENTS
    ===================================================== */

    if (
        current.decision &&
        current.decision.toString()
            == 'Additional Documents Required'
    ) {

        createNotification(

            studentID,

            'Document Re-upload Required',

            'Additional documents are required for Visa Case ' +
            current.getDisplayValue('number') +
            '. Please review your case and upload the requested documents.',

            'warning'

        );

    }


    /* =====================================================
       2. ADVISOR ASSIGNED
    ===================================================== */

    if (
        current.advisor.changes() &&
        !current.advisor.nil()
    ) {

        createNotification(

            studentID,

            'Advisor Assigned',

            'An advisor has been assigned to your Visa Case ' +
            current.getDisplayValue('number') +
            '.',

            'info'

        );


        /*
         * Notify advisor
         */

        createNotification(

            current.advisor.toString(),

            'Visa Case Assigned',

            'Visa Case ' +
            current.getDisplayValue('number') +
            ' has been assigned to you. Please review the case.',

            'info'

        );

    }


    /* =====================================================
       3. DSO DECISION
    ===================================================== */

    if (
        current.dso_decision.changes()
    ) {

        var decision =
            current.dso_decision.toString();


        if (
            decision == 'Approved'
        ) {

            createNotification(

                studentID,

                'Visa Application Approved',

                'Your Visa Application ' +
                current.getDisplayValue('number') +
                ' has been approved by the DSO.',

                'success'

            );

        }


        if (
            decision == 'Rejected'
        ) {

            createNotification(

                studentID,

                'Visa Application Decision',

                'Your Visa Application ' +
                current.getDisplayValue('number') +
                ' has been rejected. Please review the case details.',

                'danger'

            );

        }

    }


    /* =====================================================
       4. ADVISOR DOCUMENTS
    ===================================================== */

    if (
        current.advisor_document_status &&
        current.advisor_document_status.changes() &&
        current.advisor_document_status.toString()
            == 'Uploaded'
    ) {

        createNotification(

            studentID,

            'Advisor Documents Uploaded',

            'Your advisor has uploaded new documents to Visa Case ' +
            current.getDisplayValue('number') +
            '.',

            'success'

        );

    }


    /* =====================================================
       5. ADVISOR SLA
    ===================================================== */

    if (
        current.advisor_sla_status &&
        current.advisor_sla_status.changes() &&
        current.advisor_sla_status.toString()
            == 'Breached'
    ) {

        createNotification(

            studentID,

            'Advisor SLA Breached',

            'The advisor SLA for Visa Case ' +
            current.getDisplayValue('number') +
            ' has been breached.',

            'warning'

        );

    }


    /* =====================================================
       6. DSO SLA
    ===================================================== */

    if (
        current.dso_sla_status &&
        current.dso_sla_status.changes() &&
        current.dso_sla_status.toString()
            == 'Breached'
    ) {

        createNotification(

            studentID,

            'DSO SLA Breached',

            'The DSO SLA for Visa Case ' +
            current.getDisplayValue('number') +
            ' has been breached.',

            'warning'

        );

    }


})(current, previous);
